import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8IeflXD.js";var i=JSON.parse(`{"title":"Slots","description":"","frontmatter":{},"headers":[],"relativePath":"reference-slots.md","filePath":"pages/reference-slots.md"}`),a={name:`reference-slots.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to “Slots”">​</a></h1><p>The full slot surface: which slots exist, which ones the renderer reads, and what each one is handed.</p><p><code>Slots&lt;TRow&gt;</code> and <code>Slot&lt;Ctx&gt;</code> are declared in <code>src/0_types.ts</code>. A slot is a function returning anything renderable, or a signal of one.</p><h2 id="what-the-renderer-reads" tabindex="-1">What the renderer reads <a class="header-anchor" href="#what-the-renderer-reads" aria-label="Permalink to “What the renderer reads”">​</a></h2><table tabindex="0"><thead><tr><th>slot</th><th>drawn at</th><th>beaten by</th></tr></thead><tbody><tr><td><code>cell</code></td><td>every data cell</td><td><code>ColumnDef.cell</code></td></tr><tr><td><code>editor</code></td><td>a cell while <code>state.editing</code> names it</td><td>nothing</td></tr><tr><td><code>header</code></td><td>every header cell</td><td><code>ColumnDef.headerCell</code></td></tr><tr><td><code>expander</code></td><td>the disclosure glyph</td><td>nothing</td></tr><tr><td><code>detail</code></td><td>an open detail panel row</td><td>nothing</td></tr></tbody></table><p>The pick order resolves in one line inside <code>src/10_render.ts</code>: an editor wins while the cell is editing, the column beats the schema, and absent means the built-in text path.</p><h2 id="declared-and-unread" tabindex="-1">Declared and unread <a class="header-anchor" href="#declared-and-unread" aria-label="Permalink to “Declared and unread”">​</a></h2><p><code>headerGroup</code>, <code>row</code>, <code>checkbox</code>, <code>resizeHandle</code>, <code>dragPreview</code>, <code>empty</code>, <code>loading</code>, and <code>footer</code> are declared on <code>Slots</code> and render nothing today. A grid needing an empty state or a footer places that node beside the grid rather than inside it.</p><h2 id="the-three-contexts" tabindex="-1">The three contexts <a class="header-anchor" href="#the-three-contexts" aria-label="Permalink to “The three contexts”">​</a></h2><table tabindex="0"><thead><tr><th>ctx</th><th>fields</th><th>handed to</th></tr></thead><tbody><tr><td><code>CellCtx</code></td><td><code>row</code>, <code>col</code>, <code>data</code>, <code>value</code>, <code>node</code>, <code>editing</code></td><td><code>cell</code>, <code>editor</code></td></tr><tr><td><code>HeaderCtx</code></td><td><code>col</code>, <code>node</code>, <code>sort</code>, <code>pinned</code></td><td><code>header</code></td></tr><tr><td><code>RowCtx</code></td><td><code>row</code>, <code>data</code>, <code>node</code>, <code>selected</code>, <code>open</code></td><td><code>expander</code>, <code>detail</code></td></tr></tbody></table><p>The shapes are fixed. A slot needing more closes over it, because a slot is an ordinary function in your own scope.</p><h2 id="returning-a-signal" tabindex="-1">Returning a signal <a class="header-anchor" href="#returning-a-signal" aria-label="Permalink to “Returning a signal”">​</a></h2><p><code>mount</code> in <code>src/10_render.ts</code> subscribes a returned signal into the row&#39;s own <code>Subscription</code> and replaces only what the previous emission inserted, so one cell updates and the row around it never rebuilds. Worked through on <a href="/hafley-rxjs/signal-grid/cells-signal-slots">Slots that are signals</a>.</p><h2 id="no-value-and-onchange-pairs" tabindex="-1">No value and onChange pairs <a class="header-anchor" href="#no-value-and-onchange-pairs" aria-label="Permalink to “No value and onChange pairs”">​</a></h2><p>Controlled is one signal you hold rather than two props you pair, because a signal is both halves in one object. The argument is on <a href="/hafley-rxjs/signal-grid/why-signals">Signals instead of value and onChange</a>.</p><h2 id="the-reference-live-slot" tabindex="-1">The reference live slot <a class="header-anchor" href="#the-reference-live-slot" aria-label="Permalink to “The reference live slot”">​</a></h2><p><code>checkboxColumn</code> in <code>src/5_columns.ts</code> builds a header slot returning a signal that reads the flat view and the selection record and answers one of three glyphs, counting neither group headings nor detail panels. It is the select-all toggle, and it is the shape to copy for any header that has to watch the body.</p>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};